/* Auto-generated sample data for dbo.DailyPerformance.
   Covers the last 66 days across 6 hospitals and 46 metrics.
   Re-running is safe: rows are keyed by (ReportDate, HospitalId, MetricCode) and skipped if present. */

SET NOCOUNT ON;

IF OBJECT_ID('tempdb..#Hosp') IS NOT NULL DROP TABLE #Hosp;
SELECT HospitalId, HospitalCode INTO #Hosp FROM dbo.Hospitals;

IF OBJECT_ID('tempdb..#Stage') IS NOT NULL DROP TABLE #Stage;
CREATE TABLE #Stage (
  ReportDate DATE, HospitalCode VARCHAR(10), Category VARCHAR(120), MetricCode VARCHAR(50), MetricName VARCHAR(200),
  Unit VARCHAR(20), ActualValue DECIMAL(18,4), LowerIsBetter BIT, SortOrder INT
);






















SELECT s.ReportDate, h.HospitalId, s.Category, s.MetricCode, s.MetricName, s.Unit, s.ActualValue, s.LowerIsBetter, s.SortOrder
FROM #Stage s
JOIN #Hosp h ON h.HospitalCode = s.HospitalCode
WHERE NOT EXISTS (
  SELECT 1 FROM dbo.DailyPerformance dp
  WHERE dp.ReportDate = s.ReportDate AND dp.HospitalId = h.HospitalId AND dp.MetricCode = s.MetricCode
);

;WITH Cum AS (
  SELECT dp.DailyPerformanceId,
    CASE WHEN dp.Unit IN ('count','LKR')
      THEN SUM(dp.ActualValue) OVER (PARTITION BY dp.HospitalId, dp.MetricCode, YEAR(dp.ReportDate), MONTH(dp.ReportDate) ORDER BY dp.ReportDate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
      ELSE AVG(dp.ActualValue) OVER (PARTITION BY dp.HospitalId, dp.MetricCode, YEAR(dp.ReportDate), MONTH(dp.ReportDate) ORDER BY dp.ReportDate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
    END AS MTDCalc
  FROM dbo.DailyPerformance dp
)
UPDATE dp SET dp.MTDValue = ROUND(c.MTDCalc, 2)
FROM dbo.DailyPerformance dp JOIN Cum c ON c.DailyPerformanceId = dp.DailyPerformanceId;

IF OBJECT_ID('tempdb..#MonthTotals') IS NOT NULL DROP TABLE #MonthTotals;
;WITH MonthEnd AS (
  SELECT HospitalId, MetricCode, DATEFROMPARTS(YEAR(ReportDate),MONTH(ReportDate),1) AS MonthStart, MTDValue,
    ROW_NUMBER() OVER (PARTITION BY HospitalId, MetricCode, YEAR(ReportDate), MONTH(ReportDate) ORDER BY ReportDate DESC) rn
  FROM dbo.DailyPerformance
)
SELECT HospitalId, MetricCode, MonthStart, MTDValue AS MTDFinal INTO #MonthTotals FROM MonthEnd WHERE rn = 1;

UPDATE dp SET dp.PriorMonthValue = t.MTDFinal
FROM dbo.DailyPerformance dp
JOIN #MonthTotals t ON t.HospitalId = dp.HospitalId AND t.MetricCode = dp.MetricCode
  AND t.MonthStart = DATEADD(MONTH,-1,DATEFROMPARTS(YEAR(dp.ReportDate),MONTH(dp.ReportDate),1));

IF OBJECT_ID('tempdb..#MetricFlags') IS NOT NULL DROP TABLE #MetricFlags;
CREATE TABLE #MetricFlags (MetricCode VARCHAR(50), HasBudget BIT, HasTarget BIT, TargetValue DECIMAL(18,4) NULL, HasPriorYear BIT);

UPDATE dp SET
  dp.TargetValue = CASE WHEN f.HasTarget=1 THEN f.TargetValue ELSE NULL END,
  dp.BudgetValue = CASE WHEN f.HasBudget=1 THEN ROUND(t.MTDFinal * (0.88 + (ABS(CHECKSUM(dp.HospitalId,dp.MetricCode)) % 100)/100.0*0.24), 2) ELSE NULL END,
  dp.PriorYearValue = CASE WHEN f.HasPriorYear=1 THEN ROUND(t.MTDFinal * (0.80 + (ABS(CHECKSUM(dp.MetricCode,dp.HospitalId)) % 100)/100.0*0.35), 2) ELSE NULL END
FROM dbo.DailyPerformance dp
JOIN #MetricFlags f ON f.MetricCode = dp.MetricCode
JOIN #MonthTotals t ON t.HospitalId = dp.HospitalId AND t.MetricCode = dp.MetricCode
  AND t.MonthStart = DATEFROMPARTS(YEAR(dp.ReportDate),MONTH(dp.ReportDate),1);

DROP TABLE #Stage;
DROP TABLE #Hosp;
DROP TABLE #MonthTotals;
DROP TABLE #MetricFlags;
